<script setup lang="ts">import {ref} from 'vue';import type {Note,User} from '../types/domain';import {researchApi} from '../api/research';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Badge from '../components/common/Badge.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';defineProps<{notes:Note[];user:User;reload:()=>Promise<any>}>();const review=ref('确认主题由人工命名，稳定性不当作语义真值；代表文档继续人工阅读，不称概率后验。');const {task,act}=useAsync()</script><template><PageTitle index="05 / EDITORIAL REVIEW" title="名字与解释，带着依据归档。" description="说明冻结建立时的主题快照，负责人审阅后开放CSV；后续主题命名变化不会改写已审阅交付。所依据展签撤回后，说明与旧词权立即停止对外提供。"/><Notice :error="task.error" :message="task.message"/><label v-if="user.role==='admin'" class="review-note">本次负责人审阅说明<input v-model="review" maxlength="500"/></label><Empty v-if="!notes.length" title="没有编辑说明" help="在词权与稳定页先人工命名主题，再记录说明。"/><div class="note-list"><article v-for="n in notes" :key="n.id" :class="{quarantined:!n.exportable&&n.status==='approved'}"><header><span class="note-number">{{String(n.id).padStart(2,'0')}}</span><div><small>RUN / {{n.run_id}} · {{n.profile_snapshot.map(p=>p.label).join('、')}}</small><h2>{{n.name}}</h2></div><Badge :status="n.status"/><Badge v-if="n.quarantine_reason" status="invalidated"/></header><div v-if="n.quarantine_reason" class="notice error" role="alert"><strong>已隔离 / 不可下载。</strong> {{n.quarantine_reason}}。旧词权快照与导出对外关闭，仅保留说明编号、主题编号与审阅记录供追溯；请在新替代运行上重新建立并审阅说明。</div><div class="note-copy"><section><small>人工编辑解释</small><p>{{n.interpretation}}</p></section><section><small>下一步阅读与改稿</small><p>{{n.next_step}}</p></section></div><div v-if="n.review_note" class="review-copy"><small>负责人审阅</small><p>{{n.review_note}}</p></div><div class="note-actions"><button :disabled="!n.exportable" :title="n.exportable?'':'受污染旧版或未获批，停止对外提供'" @click="act(()=>researchApi.export(n.id),'获批编辑CSV已导出')">{{n.exportable?'导出获批CSV ↗':'已隔离，不可导出'}}</button><template v-if="user.role==='admin'&&n.status==='draft'&&!n.quarantine_reason"><button :disabled="task.busy" @click="act(async()=>{await researchApi.approve(n.id,'rejected',review);await reload()},'说明已退回')">退回</button><button class="primary" :disabled="task.busy" @click="act(async()=>{await researchApi.approve(n.id,'approved',review);await reload()},'编辑说明已确认')">确认编辑说明 →</button></template></div></article></div></template>
